/**
 * Linker Script Generator untuk Nusantara Kernel (x86_64 Higher-Half).
 */

export interface LinkerScriptOptions {
  entryPoint?: string;
  physicalBase?: string;
  virtualBase?: string;
}

export function generateKernelLinkerScript(options: LinkerScriptOptions = {}): string {
  const entry = options.entryPoint ?? '_start';
  const phys = options.physicalBase ?? '0x00100000'; // 1 MiB
  const virt = options.virtualBase ?? '0xFFFFFFFF80000000'; // -2 GiB higher half

  return `/*
 * Nusantara Kernel Linker Script (x86_64 Higher-Half)
 * Generated by Nusantara Compiler (Target: nusantara-x86_64-kernel)
 */

ENTRY(${entry})

KERNEL_PHYS_BASE = ${phys};
KERNEL_VIRT_BASE = ${virt};

SECTIONS
{
    . = KERNEL_PHYS_BASE;

    /* Bagian bootloader yang harus berada di bawah 1 MiB s/d 2 MiB physical */
    .boot ALIGN(4K) :
    {
        _boot_start = .;
        *(.multiboot)
        *(.boot_text)
        *(.boot_data)
        _boot_end = .;
    }

    /* Beralih ke alamat virtual higher-half */
    . += KERNEL_VIRT_BASE;

    _kernel_start = .;

    /* Bagian kode executable kernel */
    .text ALIGN(4K) : AT(ADDR(.text) - KERNEL_VIRT_BASE)
    {
        *(.text .text.*)
    }

    /* Bagian data hanya-baca */
    .rodata ALIGN(4K) : AT(ADDR(.rodata) - KERNEL_VIRT_BASE)
    {
        *(.rodata .rodata.*)
    }

    /* Bagian data terbaca dan tertulis */
    .data ALIGN(4K) : AT(ADDR(.data) - KERNEL_VIRT_BASE)
    {
        *(.data .data.*)
    }

    /* Bagian BSS (uninitialized data) */
    .bss ALIGN(4K) : AT(ADDR(.bss) - KERNEL_VIRT_BASE)
    {
        _bss_start = .;
        *(COMMON)
        *(.bss .bss.*)
        _bss_end = .;
    }

    _kernel_end = .;

    /DISCARD/ :
    {
        *(.comment)
        *(.eh_frame)
        *(.note.*)
    }
}
`;
}
